static class CanteenEndpoints
{
 public static void Map(WebApplication app,Func<Database> get,object gate,Action save){
  DateOnly Month(string? value){if(value is null){var latest=get().Documents.Where(d=>d.Status=="Posted").Select(d=>d.Date).DefaultIfEmpty(DateOnly.FromDateTime(DateTime.UtcNow)).Max();return new(latest.Year,latest.Month,1);}if(!DateOnly.TryParseExact(value+"-01","yyyy-MM-dd",out var month))throw new ArgumentException("Use a valid reporting month (YYYY-MM).");return month;}
  app.MapGet("/api/canteen",(string? month)=>{lock(gate){var db=get();var date=Month(month);return Results.Ok(new{profile=db.CanteenProfile??SchoolProfile.Default(db),catalog=CanteenReports.Catalog(db,date),inputs=db.CanteenInputs,submissions=db.CanteenSubmissions,inputKinds=CanteenReports.InputKinds,source="User-provided transcription of DM 536, s. 2026 (30 October 2026). Adapted layouts; official annex form layouts have not been independently verified."});}});
  app.MapPut("/api/canteen/profile",(SchoolProfile p)=>{lock(gate){var db=get();CanteenReports.ValidateProfile(db,p);db.CanteenProfile=p;save();return Results.Ok(p);}});
  app.MapPost("/api/canteen/inputs",(CanteenInput input)=>{lock(gate){var db=get();CanteenReports.ValidateInput(input);if(input.BankId is not null){Banking.Resolve(db,input.BankId);if(!Banking.ReconciliationKinds.Contains(input.Kind))throw new ArgumentException("Only bank reconciliation records can be linked to a bank.");}if(input.Kind=="Cash-flow classification"&&!db.Documents.Any(d=>d.Status=="Posted"&&d.Number==input.Reference))throw new ArgumentException("Cash-flow reference must match a posted document number.");if(new[]{"Verified closing inventory","Bank statement balance"}.Contains(input.Kind)&&input.Date.Day!=DateTime.DaysInMonth(input.Date.Year,input.Date.Month))throw new ArgumentException("Closing inventory and bank statement balances must be dated at month-end.");input=input with{Id=Guid.NewGuid().ToString()};if(new[]{"Verified closing inventory","Bank statement balance"}.Contains(input.Kind)&&db.CanteenInputs.Any(i=>i.Kind==input.Kind&&i.Date==input.Date&&(input.Kind!="Bank statement balance"||Banking.InScope(db,i,Banking.Resolve(db,input.BankId)))))throw new ArgumentException("A balance already exists for this period-end. Remove it before entering a replacement.");db.CanteenInputs.Add(input);save();return Results.Ok(input);}});
  app.MapDelete("/api/canteen/inputs/{id}",(string id)=>{lock(gate){var db=get();if(db.CanteenInputs.RemoveAll(i=>i.Id==id)==0)return Results.NotFound();save();return Results.NoContent();}});
  app.MapPut("/api/canteen/submissions",(CanteenSubmission input)=>{lock(gate){if(!new[]{"A-1","A-2"}.Contains(input.Category)||input.PeriodEnd.Day!=DateTime.DaysInMonth(input.PeriodEnd.Year,input.PeriodEnd.Month)||(input.Category=="A-1"&&input.PeriodEnd.Month%3!=0))throw new ArgumentException("Select a valid category and month/quarter-end date.");if(input.AccountingRoutedOn.HasValue&&(!input.RecordsReceivedOn.HasValue||input.AccountingRoutedOn<input.RecordsReceivedOn)||input.AuditorTransmittedOn.HasValue&&(!input.AccountingRoutedOn.HasValue||input.AuditorTransmittedOn<input.AccountingRoutedOn))throw new ArgumentException("Record receipt before accounting routing and accounting routing before auditor transmission.");if((input.RecordsReceivedOn.HasValue||input.AccountingRoutedOn.HasValue||input.AuditorTransmittedOn.HasValue)&&string.IsNullOrWhiteSpace(input.Reference))throw new ArgumentException("Provide the actual receiving/routing reference.");var db=get();db.CanteenSubmissions.RemoveAll(s=>s.Category==input.Category&&s.PeriodEnd==input.PeriodEnd);input=input with{Id=Guid.NewGuid().ToString()};db.CanteenSubmissions.Add(input);save();return Results.Ok(input);}});
  app.MapGet("/api/canteen/reports/{id}",(string id,string? month,string? detail,string? bankId)=>{lock(gate){return Results.Ok(CanteenReports.Build(get(),id,Month(month),detail,bankId));}});
  app.MapGet("/api/canteen/reports/{id}/export/{format}",(string id,string format,string? month,string? detail,string? bankId)=>{lock(gate){if(!new[]{"pdf","docx","xlsx"}.Contains(format))throw new ArgumentException("Choose pdf, docx or xlsx.");var report=CanteenReports.Build(get(),id,Month(month),detail,bankId);var bytes=ReportExports.Render(report,format);return Results.File(bytes,format switch{"pdf"=>"application/pdf","docx"=>"application/vnd.openxmlformats-officedocument.wordprocessingml.document",_=>"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"},$"canteen-{id}-{report.PeriodEnd:yyyy-MM-dd}.{format}");}});
 }
}
